import type { Beat } from "./beats.js";

/**
 * The catalog: 1,528 US-listed equities and 502 crypto assets — 2,030 topics.
 *
 * Built from index constituents — the S&P 500, the S&P 400, and additions — which
 * has a blind spot worth naming: **an index list cannot see a recent IPO.**
 * SpaceX listed and was absent from this file until someone searched for it.
 * Index membership answers "what is large and established", not "what makes
 * news", and those are different sets.
 *
 * Crypto was removed once and restored deliberately. A coin trades continuously
 * and a share does not, which is an argument for keeping them legible, not for
 * excluding half the market.
 *
 * A coin and a company can share a ticker: Sui and Sun Communities are both SUI.
 * The symbol does not say which is which, so `asset` does.
 */

/**
 * Built from the S&P Composite 1500 plus the S&P 600 for small caps, and the 500
 * largest crypto assets by market cap. The extra thirty are IPOs and tokens the
 * indices have not caught up with.
 *
 * Matching is **keywords in the headline**, English only — not concept URIs.
 * That choice has a cost worth knowing: a bare short ticker is useless as a
 * keyword. `"S"` matches any headline containing the letter, `"NOW"` matches
 * the word "now", `"OP"` matches "Op-Ed". So each entry carries the
 * *distinctive name* a journalist would actually write (SentinelOne,
 * ServiceNow, Optimism) and adds the ticker only where it is unambiguous.
 *
 * `beat_id` is derived from the ticker and must never change: it is the key
 * clients store cursors against. Three ids are pinned because articles are
 * already stored under them.
 */

/* Entries 1–400. Split only because a single
   literal of this size exceeds what TypeScript will infer a type for:
   "Expression produces a union type that is too complex to represent." */
